#!/usr/bin/env python3
"""Build the static DoJa catalog, pages and exports. Python standard library only."""
from pathlib import Path
import csv,html,json,shutil
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'data/catalog.json').read_text(encoding='utf-8'))
R=D['records'];C=D['counts'];BASE=D['site_url'];REPO=D['repository'];DATE=D['snapshot_date']
SEARCH='https://keitaiarchive.org/search.html';DOWNLOADS='https://keitaiarchive.org/downloads.html'
STORY='https://medium.com/@yuviapp/the-story-to-save-a-couple-of-lost-keitai-games-1be4ede27c75'
DIRGE=next(r for r in R if r['title']=='Final Fantasy 7 - Dirge of Cerberus - Lost Episode')

def h(x):return html.escape(str(x),quote=True)
def num(n):return f'{n:,}'
def path(r):return 'games/'+r['id']+'/index.html'
def jp_display(text):return ''.join('◇' if 0xE000<=ord(c)<=0xF8FF else c for c in text)
def japanese(r):return next((t for t in r['japanese_titles'] if t and t.casefold()!=r['title'].casefold()),'')
def write(name,text):
    p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')

def nav(prefix,active=''):
    return f'''<header class="site-header"><div class="shell nav"><a class="brand" href="{prefix}index.html" aria-label="DoJa Archive home"><i aria-hidden="true"><b></b><b></b><b></b><b></b></i><span>DoJa <em>/</em> ARCHIVE</span></a><nav class="top-nav" aria-label="Main navigation"><a href="{prefix}index.html#catalog"{' aria-current="page"' if active=='catalog' else ''}>Catalog</a><a href="{prefix}about/index.html"{' aria-current="page"' if active=='about' else ''}>Sources &amp; story</a><a class="nav-source" href="https://keitaiarchive.org/" target="_blank" rel="noopener noreferrer">Keitai Archive ↗</a></nav></div></header>'''

def footer(prefix):
    return f'''<footer class="site-footer"><div class="shell foot"><div><a class="brand" href="{prefix}index.html"><i aria-hidden="true"><b></b><b></b><b></b><b></b></i><span>DoJa <em>/</em> ARCHIVE</span></a><p>An independent discovery catalog by Wakkatobakka. Original preservation, translations, and launcher work belong to the Keitai community and their credited contributors. Source material remains with its original projects.</p></div><div class="foot-links"><a href="{prefix}about/index.html">Sources &amp; credits</a><a href="https://wakkatobakka.github.io/qualcomm-brew-archive/">BREW ↗</a><a href="https://wakkatobakka.github.io/zeebo-archive/">Zeebo ↗</a><a href="https://wakkatobakka.github.io/exen-game-archive/">ExEn ↗</a><a href="{REPO}">GitHub ↗</a></div></div></footer>'''

def page(title,desc,canonical,prefix,body,active='',script=False,kind='WebPage'):
    structured=json.dumps({'@context':'https://schema.org','@type':kind,'name':title,'url':canonical,'description':desc,'isPartOf':{'@type':'WebSite','name':D['title'],'url':BASE}},ensure_ascii=False).replace('<','\\u003c')
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#100f18"><title>{h(title)}</title><meta name="description" content="{h(desc)}"><link rel="canonical" href="{h(canonical)}"><meta property="og:type" content="website"><meta property="og:title" content="{h(title)}"><meta property="og:description" content="{h(desc)}"><meta property="og:url" content="{h(canonical)}"><meta property="og:image" content="{BASE}assets/social-preview.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/styles.css"><script type="application/ld+json">{structured}</script></head><body><a class="skip" href="#main">Skip to content</a>{nav(prefix,active)}<main id="main">{body}</main>{footer(prefix)}{f'<script src="{prefix}assets/app.js" defer></script>' if script else ''}</body></html>\n'''

def flags(e):
    values=[]
    if e['patch_label']:values.append(e['patch_label'].replace('ENGLISH PATCH','English patch').replace('CHINESE PATCH','Chinese patch'))
    if e['trial_label']:values.append(e['trial_label'])
    if not values:values.append('Unmarked source entry')
    return values

def card(r):
    entry_count=len(r['entries']);j=japanese(r)
    labels=[]
    if any(e['patch_language']=='English' for e in r['entries']):labels.append('EN patch')
    if any(e['patch_language']=='Chinese' for e in r['entries']):labels.append('ZH patch')
    if any(e['trial_label'] for e in r['entries']):labels.append('Trial listed')
    summary=' · '.join(labels) or 'Source-listed'
    terms=' '.join([r['title'],*r['japanese_titles'],*r['aliases'],*(e['source_filename']+' '+e['source_variant_text'] for e in r['entries'])])
    filters=[{'patch':e['patch_language'] if e['patch_label'] else '', 'trial':bool(e['trial_label']), 'sd':e['sd_data_listed']} for e in r['entries']]
    return f'''<a class="record" href="{path(r)}" data-name="{h(r['title'])}" data-count="{entry_count}" data-search="{h(terms)}" data-entries="{h(json.dumps(filters,separators=(',',':')))}"><div><div class="record-top"><span class="record-year">DoJa / i-appli</span><span class="record-status">{h(summary)}</span></div><h3>{h(r['title'])}</h3>{f'<p class="jp" lang="ja">{h(jp_display(j))}</p>' if j else ''}</div><div class="record-bottom"><small>{entry_count} source {'entry' if entry_count==1 else 'entries'}</small><span class="arrow" aria-hidden="true">↗</span></div></a>'''

feature_titles=['Final Fantasy 7 - Dirge of Cerberus - Lost Episode','Devil May Cry Deadshot','Final Fantasy 7 Snowboarding','Rockman DASH, Great Adventure on 5 Islands','Monster Hunter i for SH','Sonic Jump']
featured=[next(r for r in R if r['title']==t) for t in feature_titles]
feature_cards=''.join(f'''<a class="spotlight-card" href="{path(r)}"><span class="art-no">{i:02d} / DoJa <span class="arrow" aria-hidden="true">↗</span></span><div><h3>{h(r['title'])}</h3><p>{len(r['entries'])} source {'entry' if len(r['entries'])==1 else 'entries'} · {h('English patch listed' if any(e['patch_language']=='English' for e in r['entries']) else 'Follow the source')}</p></div></a>''' for i,r in enumerate(featured,1))
phone='''<div class="hero-art" role="img" aria-label="Original illustration of a Japanese flip phone with DoJa on its screen"><div class="flip-phone"><div class="flip-speaker"></div><div class="flip-lid"><div class="flip-screen"><div class="flip-status"><span>i-appli / MEMORY</span><span>▮▮▯</span></div><strong>DoJa</strong><small>A LOST EPISODE.</small><p>A WORLD WORTH REMEMBERING.</p></div></div><div class="flip-hinge"></div><div class="flip-base"><div class="flip-pad"></div><div class="flip-keys" aria-hidden="true">'''+('<b></b>'*12)+'''</div></div></div><div class="art-label">WHERE IT STARTED<span>SMALL PHONE. LONG STORY.</span></div></div>'''
home=f'''
<section class="shell hero"><div><div class="eyebrow"><span class="pulse"></span> WAKKA'S JAPANESE MOBILE HISTORY INDEX</div><h1>A lost episode.<br><em>A whole world<br>behind it.</em></h1><p class="hero-lede">One recovered Final Fantasy game opened the door. Beyond it: tiny-screen adventures, unexpected spin-offs, and a community bringing Japanese mobile history back into reach. Follow {num(C['included_doja_entries'])} source-listed DoJa entries.</p><div class="buttons"><a class="btn btn-primary" href="#catalog">Explore the catalog ↘</a><a class="btn btn-secondary" href="{path(DIRGE)}">Start with Dirge ↗</a></div><p class="small-flag">A snapshot of the Keitai World Launcher catalog, reviewed {DATE}.</p></div>{phone}</section>
<section class="statband" aria-label="Catalog scope"><div class="shell stats"><div class="stat"><strong class="mint">{num(len(R))}</strong><span>grouped title &amp; application records</span></div><div class="stat"><strong class="amber">{num(C['included_doja_entries'])}</strong><span>DoJa source entries retained</span></div><div class="stat"><strong>{C['english_patch_entries']+C['chinese_patch_entries']}</strong><span>entries labeled with a translation patch</span></div><div class="stat"><strong>{C['trial_labeled_entries']}</strong><span>entries explicitly labeled as trials or demos</span></div></div></section>
<section class="shell intro"><div><div class="kicker">A DIFFERENT MOBILE WORLD</div><h2>Before the app store.<br>Beyond the familiar.</h2></div><div><p>DoJa was the Java application environment behind a branch of NTT DoCoMo's i-mode software. The surviving catalog runs from familiar game series to small experiments, utilities, and applications that seldom traveled beyond their original phones.</p><p>This guide follows the entries explicitly labeled <strong>DoJa</strong> by Keitai World Launcher. Japanese source titles, patch labels, handset variants, and separate SD-data references stay attached to their records.</p><a class="text-link" href="about/index.html">Meet the sources and preservation community ↗</a></div></section>
<section class="shell spotlight"><div class="spotlight-header"><div><div class="kicker">SIX DOORS INTO THE CATALOG</div><h2>Familiar names. Unfamiliar chapters.</h2></div><p>Some of the games that pulled Wakka into this corner of mobile history.</p></div><div class="spotlight-grid">{feature_cards}</div></section>
<section class="shell origin" aria-labelledby="origin-title"><div><div class="kicker">WHERE THIS COLLECTION BEGAN</div><h2 id="origin-title">Dirge opened the door.</h2><p>Dirge of Cerberus: Lost Episode was Wakka's starting point for building Android bridges. This archive returns to that beginning and opens the catalog around it.</p><p class="origin-sign">The preservation work came first. This guide follows its trail.</p></div><div class="origin-context"><p>Yuvi's account of restoring the full release describes the SD-card recovery effort and credits Naoya Shinota and other contributors. Their work, alongside the wider Keitai community, is part of the story behind the game reaching modern players.</p><div class="buttons"><a class="btn btn-primary" href="{path(DIRGE)}">Explore the Dirge record ↗</a><a class="btn btn-secondary" href="{STORY}" target="_blank" rel="noopener noreferrer">Read Yuvi's account ↗</a></div></div></section>
<section class="catalog-wrap" id="catalog"><div class="shell"><div class="catalog-header"><div class="kicker">THE DOJA INDEX</div><h2>Find another lost chapter.</h2><p class="sub">Browse {num(len(R))} records. Recognized patches and trial editions share a page, with every original source entry retained. Search includes Japanese titles, filenames, and source-listed variants.</p></div><noscript><p class="no-script">All records appear below. Enable JavaScript for search, filters, and pages of 60 records.</p></noscript><div class="filters" id="catalog-filters" hidden><div class="filter search-filter"><label for="game-search">Search titles, Japanese names, or variants</label><input id="game-search" type="search" placeholder="Try Dirge, Rockman, ﾓﾝｽﾀｰﾊﾝﾀｰ…" maxlength="150" autocomplete="off"></div><div class="filter"><label for="edition-filter">Edition label</label><select id="edition-filter"><option value="">All entries</option><option value="english">English patch</option><option value="chinese">Chinese patch</option><option value="trial">Trial / demo label</option><option value="unmarked">Unmarked source entry</option></select></div><div class="filter"><label for="sd-filter">SD-data reference</label><select id="sd-filter"><option value="">All entries</option><option value="yes">Listed separately</option><option value="no">Not listed</option></select></div><div class="filter"><label for="sort-by">Sort by</label><select id="sort-by"><option value="title">Title A–Z</option><option value="reverse">Title Z–A</option><option value="entries">Most source entries</option></select></div></div><div class="results-row"><span id="result-count" aria-live="polite">{num(len(R))} catalog records</span><button class="reset-filters" id="reset-filters" type="button" hidden>Clear filters</button></div><div class="catalog-grid" id="game-list">{''.join(card(r) for r in R)}</div><div class="empty-state" id="no-results" hidden>No matching records. Try another title or clear the filters.</div><nav class="pagination" id="pagination" aria-label="Catalog pages" hidden><button class="btn btn-secondary" type="button" id="previous-page">← Previous</button><span id="page-count" aria-live="polite"></span><button class="btn btn-secondary" type="button" id="next-page">Next →</button></nav><div class="metadata-downloads"><div><h3>Keep the trail.</h3><p>Download the title index or the individual source-entry metadata.</p></div><div class="buttons"><a class="btn btn-secondary" href="data/catalog.csv" download>Title index CSV ↓</a><a class="btn btn-secondary" href="data/entries.csv" download>Source entries CSV ↓</a><a class="btn btn-secondary" href="data/catalog.json" download>Complete JSON ↓</a></div></div><p class="trail-note">Source-listed applications include games and other software. Patch tags describe source labels; unmarked entries have no confirmed language here. Package contents and playability were not tested for this catalog.</p></div></section>'''
write('index.html',page(D['title'],f"Explore {num(C['included_doja_entries'])} source-listed DoJa entries, Japanese titles, translation labels and handset variants. An independent guide to Keitai preservation.",BASE,'',home,'catalog',True,'CollectionPage'))

for idx,r in enumerate(R):
    j=japanese(r);entries=r['entries'];entry_ids=[];blocks=[]
    for e in entries:
        entry_ids.append(e['id'])
        variants=''.join(f'<span class="chip">{h(v)}</span>' for v in e['variant_labels'])
        variant_block=f'<h3>Source-listed variants</h3><div class="chips">{variants}</div><p class="fact-note">These are the source\'s exact variant labels. Words such as “Patched” or “Non-Working” are source descriptions, not tests performed by this catalog.</p>' if variants else '<p class="fact-note">No variant labels are provided for this entry in the source list.</p>'
        jp=e['source_japanese_title']
        blocks.append(f'''<section class="entry-block" id="{e['id']}"><h3 class="edition-title">{h(e['source_title'])}</h3><div class="edition-flags">{''.join(f'<span class="chip mint">{h(v)}</span>' for v in flags(e))}</div><dl class="facts"><div class="wide"><dt>Original package label</dt><dd><code>{h(e['source_filename'])}</code></dd></div><div class="wide"><dt>Japanese-title field in source</dt><dd lang="ja">{h(jp_display(jp)) if jp else 'Not recorded'}</dd></div><div><dt>Runtime label</dt><dd>{h(e['source_platform'])}</dd></div><div><dt>Language evidence</dt><dd>{h(e['patch_language']+' patch label' if e['patch_label'] else 'Not specified by a patch label')}</dd></div><div><dt>Separate SD-data reference</dt><dd>{'Listed in source' if e['sd_data_listed'] else 'Not listed in source'}</dd></div><div><dt>Snapshot entry number</dt><dd>{e['source_row']} of {C['source_game_list_entries']}</dd></div></dl>{variant_block}</section>''')
    own_bridge=''
    if r['id']==DIRGE['id']:
        own_bridge=f'''<div class="side-meta"><h3>Wakka's starting point</h3><p>Dirge began Wakka's Android bridge work. The bridge is a separate project with its own requirements and compatibility notes.</p><a class="source-url" href="https://github.com/Wakkatobakka/Dirge-Bridge" target="_blank" rel="noopener noreferrer">Dirge Bridge on GitHub ↗</a></div><div class="side-meta"><h3>Preservation story</h3><a class="source-url" href="{STORY}" target="_blank" rel="noopener noreferrer">Read Yuvi's firsthand account ↗</a></div>'''
    previous=R[(idx-1)%len(R)];following=R[(idx+1)%len(R)]
    pua=any(0xE000<=ord(c)<=0xF8FF for e in entries for c in e['source_japanese_title'])
    glyph_note='<p class="fact-note">A ◇ marks a carrier-specific glyph that may need an original handset font. Exact source characters are retained in the JSON export.</p>' if pua else ''
    body=f'''<section class="shell detail-hero"><div class="breadcrumbs"><a href="../../index.html">Archive</a><span>/</span><a href="../../index.html#catalog">Catalog</a><span>/</span><span>DoJa record</span></div><div class="eyebrow"><span class="pulse"></span> DOJA / SOURCE-LINKED RECORD</div><h1>{h(r['title'])}</h1>{f'<p class="detail-title-jp" lang="ja">{h(jp_display(j))}</p>' if j else ''}<div class="chips"><span class="chip">DoJa / i-appli</span><span class="chip mint">{len(entries)} source {'entry' if len(entries)==1 else 'entries'}</span>{'<span class="chip">Separate SD data listed</span>' if any(e['sd_data_listed'] for e in entries) else ''}</div></section><section class="shell detail-layout"><article class="article-panel"><h2>Follow the editions.</h2><p>Original labels and filenames from Keitai World Launcher. Recognized trial and translation labels are grouped for browsing; each entry and its variant labels stay separate below.</p>{''.join(blocks)}{glyph_note}<hr><h2>What this record establishes</h2><p>The source catalog labels these entries as DoJa. Game packages and separate SD archives were not downloaded or inspected for this index. Package integrity, completeness, release dates, publisher credits, and compatibility are not established by the listing alone.</p><p>A separate SD-data link records a source reference, rather than a tested requirement. A blank field does not establish that extra data is unnecessary.</p><p class="page-meta">Metadata snapshot: {DATE} · Record ID: <code>{r['id']}</code></p><div class="detail-links"><a href="../../{path(previous)}">← {h(previous['title'])}</a><a href="../../{path(following)}">{h(following['title'])} →</a></div></article><aside class="side-panel" aria-label="Find the original source"><div class="eyebrow"><span class="pulse"></span> KEEP THE SOURCE IN VIEW</div><h2 style="margin-top:18px">Find it in Keitai.</h2><p>Open Keitai Archive's search or Keitai World Launcher, then search using one of the exact entry titles shown on this page. Select the matching edition and check its original notes.</p><div class="buttons"><a class="btn btn-primary" href="{SEARCH}" target="_blank" rel="noopener noreferrer">Search Keitai Archive ↗</a><a class="btn btn-secondary" href="{DOWNLOADS}" target="_blank" rel="noopener noreferrer">Keitai World Launcher ↗</a></div><div class="side-meta"><h3>Catalog evidence</h3><p>Runtime label, source names, package labels, listed variants, and SD-data references come from the public launcher metadata. This page is an independent guide.</p><a class="source-url" href="../../about/index.html">Methods and preservation credits ↗</a></div>{own_bridge}<div class="side-meta"><h3>Help improve the record</h3><a class="source-url" href="{REPO}/issues/new?template=catalog-correction.yml">Suggest a sourced correction ↗</a></div></aside></section>'''
    write(path(r),page(r['title']+' | DoJa Archive',f"Source-linked DoJa record for {r['title']}. Browse {len(entries)} catalog entries, exact package labels, Japanese title fields and variant notes.",BASE+'games/'+r['id']+'/','../../',body))

runtime_rows=''.join(f'<tr><td>{h(k)}</td><td>{num(v)}</td><td>{"Included" if k=="doja" else "Outside this catalog"}</td></tr>' for k,v in C['source_platform_labels'].items())
source_rows=''.join(f'<li><a href="{h(s["url"])}">{h(s["name"])}</a> — {num(s["size_bytes"])} bytes; decoded as {s["encoding"]}. SHA-256: <code>{s["sha256"]}</code>.</li>' for s in D['sources'])
about=f'''<article class="narrow article"><div class="eyebrow"><span class="pulse"></span> SOURCES, PEOPLE, AND A STARTING POINT</div><h1>One game opened<br><em>a much bigger door.</em></h1><p class="lede">Dirge of Cerberus: Lost Episode began Wakka's Android bridge work. This catalog is a return to those DoJa roots, built around the source trails preserved by a much wider community.</p><h2>The preservation work comes first</h2><p><a href="https://keitaiarchive.org/">Keitai Archive</a> describes a community effort preserving Japanese feature-phone games and other media. <a href="{DOWNLOADS}">Keitai World Launcher</a>, developed by <a href="https://github.com/Yuvi-App/Keitai-World-Launcher">Yuvi and its contributors</a>, brings together resources and emulators for several keitai platforms. <a href="https://keitaiwiki.com/">Keitai Wiki</a> provides broader historical documentation.</p><p>Original dumping, recovery, translation, and emulator credits remain with those projects and their credited contributors. The launcher catalog does not supply complete per-entry contributor credits; none are invented here. Source corrections and missing credits are welcome.</p><h2>Dirge's place in the story</h2><p>In <a href="{STORY}">his August 3, 2026 account</a>, Yuvi describes restoring access to the full Lost Episode release using recovered SD-card data, and credits Naoya Shinota and other contributors. The account explains the work behind the preserved game. Wakka's bridge and this catalog follow that preservation effort.</p><p>The <a href="../{path(DIRGE)}">Dirge record</a> retains the standard source listing, trial, and English-patch listing separately, together with the source's SD-data references and trial-variant labels.</p><h2>What counts as DoJa here?</h2><p><a href="https://keitaiarchive.org/resources.html">Keitai Archive's resources</a> distinguishes the DoJa and STAR SDK families. This catalog uses the launcher's explicit <code>Emulator=doja</code> field. A DoCoMo carrier label alone is too broad: other runtimes and media also belong to that carrier.</p><div class="table-wrap"><table class="edition-table"><thead><tr><th>Source runtime label</th><th>Entries</th><th>Scope</th></tr></thead><tbody>{runtime_rows}</tbody></table></div><h2>Counting entries and title records</h2><p>The source XML snapshot contains <strong>{num(C['source_game_list_entries'])} entries</strong>, including <strong>{num(C['included_doja_entries'])} explicitly labeled DoJa</strong>. Those become <strong>{num(len(R))} browsing records</strong>. A record can contain an original listing, a trial, and translation patches. Recognized patch prefixes and bracketed, parenthesized, or explicit Trial Version / Demo Version suffixes are removed only for grouping. One documented display-name alias joins “Final Fantasy VII Snowboarding” to “Final Fantasy 7 Snowboarding.” Other title differences remain distinct.</p><p>These are title and application records, rather than a count of distinct retail games. Device variants remain labels within their source entry; they are not counted as extra catalog entries. Grouping names does not verify byte equivalence, completeness, or compatibility between editions.</p><h2>Names, language, and unknowns</h2><p>English and Japanese source-title fields are preserved, including half-width characters. Exact patch labels identify {C['english_patch_entries']} English-patch entries and {C['chinese_patch_entries']} Chinese-patch entries. An entry without a patch label is shown as <strong>unmarked</strong>; its language is not inferred from its title. Trial labels are taken from explicit source-title suffixes.</p><p>Carrier-specific private-use glyphs appear as ◇ in the interface; original code points remain in the JSON export. Publication years, publisher/developer credits, translator identities, SDK version requirements, and playability are left open when the metadata does not establish them.</p><h2>What an SD-data reference means</h2><p><strong>{C['entries_with_sd_data_reference']} entries</strong> have a separate SD-data URL in the source metadata. This index records the presence of that reference without fetching its contents. Presence is not a tested requirement, and absence does not prove that an application is self-contained. <strong>{C['entries_with_variant_labels']} entries</strong> carry variant labels, which remain exact source text.</p><h2>Two public metadata snapshots</h2><p>The primary source is the XML game list configured by the official Keitai World Launcher download. Only its configuration metadata was read from the launcher ZIP. No launcher binaries were executed and no game packages, screenshots, SDKs, or SD-data packages were retrieved.</p><p>The public website CSV is used as a second name reference. {num(C['entries_with_exact_website_name_match'])} included entries have an exact name match there; the remaining {C['included_doja_entries']-C['entries_with_exact_website_name_match']} are exact-string differences, not a claim that those games are missing. Source names are retained without guessing replacements.</p><ul class="source-fingerprints">{source_rows}</ul><p>Reviewed {DATE}. Hashes identify the metadata snapshots, not any game package. The full JSON and <a href="../data/classification.csv">classification audit</a> preserve the counting trail.</p><h2>Follow the original projects</h2><div class="buttons"><a class="btn btn-primary" href="https://keitaiarchive.org/">Keitai Archive ↗</a><a class="btn btn-secondary" href="{DOWNLOADS}">Keitai World Launcher ↗</a><a class="btn btn-secondary" href="https://keitaiwiki.com/">Keitai Wiki ↗</a></div><h2>Report an error or missing credit</h2><p>Include the record ID, exact source-entry title, and a supporting reference in an <a href="{REPO}/issues/new?template=catalog-correction.yml">error report</a>. Missing preservation and translation credits can be reported the same way. Wakka reviews reports and publishes any updates.</p><p>Independent site code and presentation by Wakkatobakka. No affiliation with NTT DoCoMo or game rights holders. Game copyrights, trademarks, translations, and original project materials retain their respective ownership. This catalog links back to source projects and hosts metadata and original site material.</p><div class="buttons"><a class="btn btn-primary" href="../index.html#catalog">Return to the catalog ↗</a></div></article>'''
write('about/index.html',page('Sources & story | DoJa Archive','The sources, counting rules, and preservation credits behind Wakka’s independent DoJa catalog.',BASE+'about/','../',about,'about'))
notfound=f'<section class="narrow article"><div class="eyebrow">NO SIGNAL / 404</div><h1>Lost between episodes.</h1><p class="lede">This page is outside the catalog. Return to the index to find the title you need.</p><a class="btn btn-primary" href="{BASE}index.html#catalog">Return to the archive ↗</a></section>'
write('404.html',page('Page not found | DoJa Archive','Return to the DoJa catalog.',BASE,BASE,notfound))

with (ROOT/'data/catalog.csv').open('w',encoding='utf-8',newline='') as f:
    fields=['record_id','title','japanese_titles','source_entry_count','english_patch_listed','chinese_patch_listed','trial_listed','sd_reference_listed','record_url','source_url','snapshot_date']
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
    for r in R:
        w.writerow(dict(zip(fields,[r['id'],r['title'],' | '.join(r['japanese_titles']),len(r['entries']),any(e['patch_language']=='English' for e in r['entries']),any(e['patch_language']=='Chinese' for e in r['entries']),any(e['trial_label'] for e in r['entries']),any(e['sd_data_listed'] for e in r['entries']),BASE+'games/'+r['id']+'/',SEARCH,DATE])))
with (ROOT/'data/entries.csv').open('w',encoding='utf-8',newline='') as f:
    fields=['record_id','entry_id','source_row','source_title','source_japanese_title','source_filename','source_platform','patch_label','patch_language','trial_label','sd_data_listed','source_variant_text','website_exact_name_match','package_inspected','runtime_tested','snapshot_date']
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
    for r in R:
        for e in r['entries']:
            row={k:e.get(k,'') for k in fields};row.update(record_id=r['id'],entry_id=e['id'],snapshot_date=DATE);w.writerow(row)
urls=[BASE,BASE+'about/']+[BASE+'games/'+r['id']+'/' for r in R]
write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{h(u)}</loc><lastmod>{DATE}</lastmod></url>\n' for u in urls)+'</urlset>\n')
write('robots.txt',f'User-agent: *\nAllow: /\nSitemap: {BASE}sitemap.xml\n')
write('.nojekyll','')
# Remove stale generated record pages after an intentional metadata refresh.
valid={r['id'] for r in R}
for d in (ROOT/'games').iterdir():
    if d.is_dir() and d.name not in valid and (d/'index.html').exists():shutil.rmtree(d)
print(f'Built {len(R):,} record pages from {C["included_doja_entries"]:,} source entries, plus home, about, 404 and exports.')
